# Storyboard: sentence index -> shot spec(s). "C" = continue previous shot.
F = 1000
def J(x, **k): d = dict(who="J", x=x); d.update(k); return d
def L(x, **k): d = dict(who="L", x=x); d.update(k); return d
def R(x, **k): d = dict(x=x); d.update(k); return d
def K(cam, **p): return dict(sc="kitchen", cam=cam, p=p)
def PA(cam, **p): return dict(sc="pantry", cam=cam, p=p)
def ST(cam, **p): return dict(sc="street", cam=cam, p=p)
def CI(cam, **p): return dict(sc="city", cam=cam, p=p)
def RF(cam, **p): return dict(sc="roof", cam=cam, p=p)
def S(name, nosub=False, **p): return dict(sc=name, cam=None, p=p, nosub=nosub)
C = "C"

def box(cx, cy, w, h): return (cx, cy, w, h)

